\title{REPA-E: Unlocking VAE for End-to-End Tuning with Latent Diffusion Transformers}


\definecolor{alphaColor}{HTML}{FF9100} \definecolor{betaColor}{HTML}{00D5FF} \definecolor{gammaColor}{HTML}{F0539B} 

