def requires_grad(model, flag=True):
    """
    Set requires_grad flag for all parameters in a model.
    """
    for p in model.parameters():
        p.requires_grad = flag

def check_grad(model):
    for p in model.parameters():
        if p.requires_grad:
            return True
    return False
