  \centering
\begin{adjustbox}{max width=0.9\linewidth}
  \begin{tabular}{ c c c c c }
    \toprule
      &         &  Equal   &    \\
      & Open        &  Inference   & Divergence   \\
      Methods      &  Vocab. &  Cost             &  Control  \\
\midrule
    DPOK\cite{dpok}\  & \xmark & \cmark & \cmark \\
    DDPO\cite{ddpo} & \xmark & \cmark & \xmark \\
