        if t_high.dim() == 0:
            t_high = t_high.expand(bs)

        std_low = t_low.reshape(*t_low.size(), *((x_t_low.dim() - t_low.dim()) * [1])) / self.num_timesteps
        mean_low = 1 - std_low
        std_high = t_high.reshape(*t_high.size(), *((x_t_low.dim() - t_high.dim()) * [1])) / self.num_timesteps
        mean_high = 1 - std_high

