+    LLVMValueRef zero = LLVMConstInt(c->i32, 0, false);
+    boxed_num = LLVMBuildICmp(c->builder, LLVMIntEQ, boxed_num, zero, "");
+    LLVMBuildCondBr(c->builder, boxed_num, num_block, tuple_block);
